+/// Builds the crates.io-compatible length-prefixed upload body from the exact
+/// `.crate` bytes. Package metadata is recovered only from the normalized
+/// manifest inside that bounded archive.
+pub(super) fn cargo_upload_body(
+    crate_bytes: &[u8],
+    package: &ReleasePackageId,
+    version: &Version,
+) -> Result<Vec<u8>, GraphError> {
+    if crate_bytes.len() > MAX_CRATE_BYTES || crate_bytes.len() > u32::MAX as usize {
+        return Err(invalid_artifact(".crate payload exceeds the upload bound"));
+    }
+    let root = format!("{}-{}", package.name(), version.render());
+    let manifest_path = format!("{root}/Cargo.toml");
+    let manifest_bytes = archive_file(crate_bytes, &root, &manifest_path, MAX_MANIFEST_BYTES)?
+        .ok_or_else(|| invalid_artifact(".crate archive has no normalized Cargo.toml"))?;
+    let manifest_source = std::str::from_utf8(&manifest_bytes)
+        .map_err(|_| invalid_artifact("normalized Cargo.toml is not UTF-8"))?;
+    let manifest: toml::Value = toml::from_str(manifest_source)
+        .map_err(|error| invalid_artifact(format!("normalized Cargo.toml is invalid: {error}")))?;
+    let package_table = manifest
+        .get("package")
+        .and_then(toml::Value::as_table)
+        .ok_or_else(|| invalid_artifact("normalized Cargo.toml has no [package] table"))?;
+    if package_table.get("name").and_then(toml::Value::as_str) != Some(package.name())
+        || package_table.get("version").and_then(toml::Value::as_str) != Some(version.render().as_str())
+    {
+        return Err(invalid_artifact(".crate package identity does not match the approved slot"));
+    }
+
+    let readme_file = package_table.get("readme").and_then(toml::Value::as_str);
+    let readme = readme_file
+        .map(|relative| {
+            validate_relative_archive_path(relative)?;
+            let path = format!("{root}/{relative}");
+            archive_file(crate_bytes, &root, &path, MAX_README_BYTES)?
+                .ok_or_else(|| invalid_artifact("declared README is absent from .crate"))
+                .and_then(|bytes| {
+                    String::from_utf8(bytes).map_err(|_| invalid_artifact("declared README is not UTF-8"))
+                })
+        })
+        .transpose()?;
+
+    let metadata = serde_json::json!({
+        "name": package.name(),
+        "vers": version.render(),
+        "deps": manifest_dependencies(&manifest)?,
+        "features": string_array_map(manifest.get("features"))?,
+        "authors": string_array(package_table.get("authors"))?,
+        "description": optional_string(package_table.get("description"))?,
+        "documentation": optional_string(package_table.get("documentation"))?,
+        "homepage": optional_string(package_table.get("homepage"))?,
+        "readme": readme,
+        "readme_file": readme_file,
+        "keywords": string_array(package_table.get("keywords"))?,
+        "categories": string_array(package_table.get("categories"))?,
+        "license": optional_string(package_table.get("license"))?,
+        "license_file": optional_string(package_table.get("license-file"))?,
+        "repository": optional_string(package_table.get("repository"))?,
+        "badges": toml_to_json_object(manifest.get("badges"))?,
+        "links": optional_string(package_table.get("links"))?,
+        "rust_version": optional_string(package_table.get("rust-version"))?,
+    });
+    let metadata = serde_json::to_vec(&metadata).map_err(|error| invalid_artifact(error.to_string()))?;
+    if metadata.len() > MAX_METADATA_BYTES || metadata.len() > u32::MAX as usize {
+        return Err(invalid_artifact("Cargo publish metadata exceeds the upload bound"));
+    }
+    let capacity = 8usize
+        .checked_add(metadata.len())
+        .and_then(|size| size.checked_add(crate_bytes.len()))
+        .ok_or_else(|| invalid_artifact("Cargo upload body length overflow"))?;
+    let mut body = Vec::with_capacity(capacity);
+    body.extend_from_slice(&(metadata.len() as u32).to_le_bytes());
+    body.extend_from_slice(&metadata);
+    body.extend_from_slice(&(crate_bytes.len() as u32).to_le_bytes());
+    body.extend_from_slice(crate_bytes);
+    Ok(body)
+}
+
+fn archive_file(
+    crate_bytes: &[u8],
+    expected_root: &str,
+    expected_path: &str,
+    max_selected_bytes: u64,
+) -> Result<Option<Vec<u8>>, GraphError> {
+    let decoder = flate2::read::GzDecoder::new(crate_bytes);
+    let mut archive = tar::Archive::new(decoder);
+    let mut selected = None;
+    let mut count = 0usize;
+    let mut total = 0u64;
+    let entries = archive.entries().map_err(|error| invalid_artifact(error.to_string()))?;
+    for entry in entries {
+        let mut entry = entry.map_err(|error| invalid_artifact(error.to_string()))?;
+        count += 1;
+        if count > MAX_ARCHIVE_ENTRIES {
+            return Err(invalid_artifact(".crate archive has too many entries"));
+        }
+        let size = entry.header().size().map_err(|error| invalid_artifact(error.to_string()))?;
+        if size > MAX_ARCHIVE_ENTRY_BYTES {
+            return Err(invalid_artifact(".crate archive entry exceeds the size bound"));
+        }
+        total = total
+            .checked_add(size)
+            .ok_or_else(|| invalid_artifact(".crate archive size overflow"))?;
+        if total > MAX_ARCHIVE_TOTAL_BYTES {
+            return Err(invalid_artifact(".crate archive exceeds the expanded-size bound"));
+        }
+        let path = entry.path().map_err(|error| invalid_artifact(error.to_string()))?;
+        validate_archive_path(&path, expected_root)?;
+        if path == std::path::Path::new(expected_path) {
+            if selected.is_some() || !entry.header().entry_type().is_file() || size > max_selected_bytes {
+                return Err(invalid_artifact("selected .crate metadata entry is duplicated or oversized"));
+            }
+            let mut bytes = Vec::with_capacity(size as usize);
+            entry
+                .read_to_end(&mut bytes)
+                .map_err(|error| invalid_artifact(error.to_string()))?;
+            selected = Some(bytes);
+        }
+    }
+    Ok(selected)
+}
+
+fn validate_archive_path(path: &std::path::Path, expected_root: &str) -> Result<(), GraphError> {
+    let mut components = path.components();
+    if components.next() != Some(std::path::Component::Normal(expected_root.as_ref()))
+        || components.any(|component| !matches!(component, std::path::Component::Normal(_)))
+    {
+        return Err(invalid_artifact(".crate archive path escapes or changes its package root"));
+    }
+    Ok(())
+}
+
+fn validate_relative_archive_path(path: &str) -> Result<(), GraphError> {
+    if path.is_empty()
+        || std::path::Path::new(path)
+            .components()
+            .any(|component| !matches!(component, std::path::Component::Normal(_)))
+    {
+        return Err(invalid_artifact("manifest path is not a safe relative archive path"));
+    }
+    Ok(())
+}
+
+fn manifest_dependencies(manifest: &toml::Value) -> Result<Vec<serde_json::Value>, GraphError> {
+    let mut dependencies = Vec::new();
+    append_dependencies(&mut dependencies, manifest.get("dependencies"), "normal", None)?;
+    append_dependencies(&mut dependencies, manifest.get("dev-dependencies"), "dev", None)?;
+    append_dependencies(&mut dependencies, manifest.get("build-dependencies"), "build", None)?;
+    if let Some(targets) = manifest.get("target").and_then(toml::Value::as_table) {
+        for (target, table) in targets {
+            append_dependencies(&mut dependencies, table.get("dependencies"), "normal", Some(target))?;
+            append_dependencies(&mut dependencies, table.get("dev-dependencies"), "dev", Some(target))?;
+            append_dependencies(&mut dependencies, table.get("build-dependencies"), "build", Some(target))?;
+        }
+    }
+    Ok(dependencies)
+}
+
+fn append_dependencies(
+    output: &mut Vec<serde_json::Value>,
+    value: Option<&toml::Value>,
+    kind: &str,
+    target: Option<&str>,
+) -> Result<(), GraphError> {
+    let Some(table) = value.map(toml::Value::as_table).transpose_value()? else {
+        return Ok(());
+    };
+    for (alias, specification) in table {
+        let (version_req, features, optional, default_features, package_name, registry) = match specification {
+            toml::Value::String(requirement) => (requirement.as_str(), Vec::new(), false, true, None, None),
+            toml::Value::Table(specification) => {
+                let requirement = specification
+                    .get("version")
+                    .and_then(toml::Value::as_str)
+                    .ok_or_else(|| invalid_artifact("published dependency has no version requirement"))?;
+                let registry = optional_string(specification.get("registry"))?;
+                if registry.as_deref().is_some_and(|registry| !registry.starts_with("http://") && !registry.starts_with("https://")) {
+                    return Err(invalid_artifact("published dependency registry is not an exact index URL"));
+                }
+                (
+                    requirement,
+                    string_array(specification.get("features"))?,
+                    specification.get("optional").and_then(toml::Value::as_bool).unwrap_or(false),
+                    specification
+                        .get("default-features")
+                        .and_then(toml::Value::as_bool)
+                        .unwrap_or(true),
+                    optional_string(specification.get("package"))?,
+                    registry,
+                )
+            }
+            _ => return Err(invalid_artifact("published dependency specification is malformed")),
+        };
+        let name = package_name.as_deref().unwrap_or(alias);
+        output.push(serde_json::json!({
+            "name": name,
+            "version_req": version_req,
+            "features": features,
+            "optional": optional,
+            "default_features": default_features,
+            "target": target,
+            "kind": kind,
+            "registry": registry,
+            "explicit_name_in_toml": package_name.as_ref().map(|_| alias),
+        }));
+    }
+    Ok(())
+}
+
+trait TransposeValue<'a> {
+    fn transpose_value(self) -> Result<Option<&'a toml::map::Map<String, toml::Value>>, GraphError>;
+}
+
+impl<'a> TransposeValue<'a> for Option<Option<&'a toml::map::Map<String, toml::Value>>> {
+    fn transpose_value(self) -> Result<Option<&'a toml::map::Map<String, toml::Value>>, GraphError> {
+        match self {
+            None => Ok(None),
+            Some(Some(table)) => Ok(Some(table)),
+            Some(None) => Err(invalid_artifact("Cargo manifest section is not a table")),
+        }
+    }
+}
+
+fn string_array(value: Option<&toml::Value>) -> Result<Vec<String>, GraphError> {
+    let Some(value) = value else { return Ok(Vec::new()) };
+    value
+        .as_array()
+        .ok_or_else(|| invalid_artifact("Cargo manifest field is not an array"))?
+        .iter()
+        .map(|entry| {
+            entry
+                .as_str()
+                .map(ToOwned::to_owned)
+                .ok_or_else(|| invalid_artifact("Cargo manifest array contains a non-string"))
+        })
+        .collect()
+}
+
+fn string_array_map(value: Option<&toml::Value>) -> Result<BTreeMap<String, Vec<String>>, GraphError> {
+    let Some(value) = value else { return Ok(BTreeMap::new()) };
+    value
+        .as_table()
+        .ok_or_else(|| invalid_artifact("[features] is not a table"))?
+        .iter()
+        .map(|(name, values)| Ok((name.clone(), string_array(Some(values))?)))
+        .collect()
+}
+
+fn optional_string(value: Option<&toml::Value>) -> Result<Option<String>, GraphError> {
+    value
+        .map(|value| {
+            value
+                .as_str()
+                .map(ToOwned::to_owned)
+                .ok_or_else(|| invalid_artifact("Cargo manifest field is not a string"))
+        })
+        .transpose()
+}
+
+fn toml_to_json_object(value: Option<&toml::Value>) -> Result<serde_json::Value, GraphError> {
+    match value {
+        None => Ok(serde_json::json!({})),
+        Some(value) if value.is_table() => serde_json::to_value(value).map_err(|error| invalid_artifact(error.to_string())),
+        Some(_) => Err(invalid_artifact("[badges] is not a table")),
+    }
+}
+
+fn invalid_artifact(reason: impl Into<String>) -> GraphError {
+    GraphError::ReleaseInvariant {
+        detail: format!("invalid exact registry artifact: {}", reason.into()),
+    }
+}
